mapper.select:
SELECT bot_id, bot_name, bot_use, bot_status, tenant_id, updated_time, creator_id
FROM bt_bot
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT bot_name
FROM bt_bot
WHERE status_cd = '00A'
AND tenant_id = #{tenantId}
AND bot_id = #{botId}

SELECT bot_id, bot_name, bot_use, bot_status
FROM bt_bot
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id IN (#{botId})

  AND bot_status = #{botStatus}


SELECT bot_id, agent_strategy
FROM bt_bot
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT page_setting_info
FROM bt_bot
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_bot
WHERE bot_id = #{botId}
  AND tenant_id = #{tenantId}
  AND status_cd = '00A'


SELECT bot_id, bot_icon
FROM bt_bot
WHERE tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_bot_favor
WHERE status_cd = '00A'
  AND bot_id = #{botId}
  AND user_id = #{userId}
  AND tenant_id = #{tenantId}

SELECT type, content FROM bt_bot_user_experience
WHERE status_cd = '00A'
  AND bot_id = #{botId}
  AND tenant_id = #{tenantId}
  AND content IS NOT NULL
ORDER BY updated_time DESC

SELECT model_id
FROM bt_bot
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND bot_id = #{botId}

SELECT DISTINCT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", CASE WHEN EXISTS (SELECT 1 FROM bt_bot_auth b WHERE b.status_cd = '00A' AND b.bot_id = a.bot_id) THEN 'T' ELSE 'F' END AS "isPublish", brpr.publish_status AS "beyondPublishStatus" FROM bt_bot a LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND brpr.tenant_id = #{query.tenantId} WHERE a.status_cd = '00A'
AND (a.bot_name LIKE
#{query.searchContent}
)
AND a.tenant_id = #{query.tenantId}
AND a.bot_id IN (#{id})
AND a.creator_id = #{query.userId}
AND EXISTS (SELECT 1 FROM bt_tenant_user b WHERE b.tenant_id = a.tenant_id AND b.status_cd = '00A' AND b.user_id = #{query.memberId})
AND a.bot_status = #{query.botStatus}
AND a.bot_status IN (#{status})
AND (a.catalog_item_id IN (#{catalogItemId}))
AND brpr.publish_status = #{query.beyondPublishStatus}
ORDER BY a.updated_time DESC

SELECT * FROM (
-- 智能应用查询 SELECT DISTINCT a.bot_id AS "resourceId", a.bot_name AS "resourceName", a.bot_use AS "resourceDesc", a.bot_icon AS "avatar", a.bot_status AS "resourceStatus", a.bot_status AS "status", a.tenant_id AS "tenantId", 'APPLICATION' AS "resourceType", brpr.publish_status AS "authStatus", a.updated_time AS "updateTime", NULL AS "sceneType", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "createUserName", a.created_time AS "createTime" FROM bt_bot a
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND brpr.creator_id = #{userId}
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND (brpr.creator_id IS NULL OR brpr.creator_id != #{userId})
LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A'
WHERE a.status_cd = '00A'
AND (a.bot_name LIKE
#{query.keyword}
OR a.bot_use LIKE
#{query.keyword}
)
AND a.bot_status IN (#{status})
AND a.tenant_id = #{query.tenantId}
UNION ALL
-- 智能体查询 SELECT DISTINCT a.scene_id AS "resourceId", a.scene_name AS "resourceName", a.scene_desc AS "resourceDesc", a.scene_icon AS "avatar", a.scene_status AS "resourceStatus", a.scene_status AS "status", a.tenant_id AS "tenantId", 'AGENT' AS "resourceType", brpr.publish_status AS "authStatus", a.updated_time AS "updateTime", a.scene_type AS "sceneType", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "createUserName", a.created_time AS "createTime" FROM bt_bot_scene a
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A' AND brpr.creator_id = #{userId}
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A' AND (brpr.creator_id IS NULL OR brpr.creator_id != #{userId})
LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A'
WHERE a.status_cd = '00A'
AND (a.scene_name LIKE
#{query.keyword}
OR a.scene_desc LIKE
#{query.keyword}
)
AND a.scene_status IN (#{status})
AND a.tenant_id = #{query.tenantId}
) combined_result ORDER BY combined_result."updateTime" DESC

SELECT COALESCE(SUM(CASE WHEN status = '0' THEN 1 ELSE 0 END), 0) AS "review", COALESCE(SUM(CASE WHEN status = '1' THEN 1 ELSE 0 END), 0) AS "shelf", COALESCE(SUM(CASE WHEN status = '2' THEN 1 ELSE 0 END), 0) AS "offShelf" FROM (
-- 智能应用查询 SELECT a.bot_status AS "status" FROM bt_bot a
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND brpr.creator_id = #{userId}
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND (brpr.creator_id IS NULL OR brpr.creator_id != #{userId})
WHERE a.status_cd = '00A'
AND (a.bot_name LIKE
#{query.keyword}
OR a.bot_use LIKE
#{query.keyword}
)
AND a.tenant_id = #{query.tenantId}
UNION ALL
-- 智能体查询 SELECT a.scene_status AS "status" FROM bt_bot_scene a
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A' AND brpr.creator_id = #{userId}
INNER JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.scene_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'AGENT' AND brpr.status_cd = '00A' AND (brpr.creator_id IS NULL OR brpr.creator_id != #{userId})
WHERE a.status_cd = '00A'
AND (a.scene_name LIKE
#{query.keyword}
OR a.scene_desc LIKE
#{query.keyword}
)
AND a.tenant_id = #{query.tenantId}
) combined_result

SELECT DISTINCT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", CASE WHEN EXISTS (SELECT 1 FROM bt_bot_auth b WHERE b.status_cd = '00A' AND b.bot_id = a.bot_id) THEN 'T' ELSE 'F' END AS "isPublish", brpr.publish_status AS "beyondPublishStatus" FROM bt_bot a LEFT JOIN bt_resource_publish_record brpr ON brpr.resource_id = a.bot_id AND brpr.publish_channel = 'BEYOND' AND brpr.resource_type = 'BOT' AND brpr.status_cd = '00A' AND brpr.tenant_id = #{query.tenantId} WHERE a.status_cd = '00A' AND a.tenant_id = #{query.tenantId}
AND a.bot_name LIKE
#{query.name}
AND a.bot_status = #{query.status}
AND brpr.publish_status = #{query.beyondPublishStatus}
ORDER BY a.updated_time DESC

SELECT * FROM ( SELECT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName" FROM bt_bot_session b LEFT JOIN bt_bot a ON a.bot_id = b.bot_id AND a.tenant_id = b.bot_tenant_id WHERE 1=1
AND b.creator_id = #{query.memberId}
ORDER BY b.updated_time DESC) TMP WHERE 1=1 10

SELECT a.bot_id, a.tenant_id, a.bot_name, a.bot_use, a.bot_status, a.data_from, a.creator_id FROM bt_bot a WHERE a.status_cd = '00A'
AND a.tenant_id = #{tenantId}
AND a.bot_id IN (#{id})

SELECT a.bot_id, a.bot_name, a.tenant_id, a.created_time, t.tenant_name, u.user_name AS creator_name FROM bt_bot a LEFT JOIN bt_tenant t ON t.tenant_id = a.tenant_id LEFT JOIN bt_user u ON u.user_id = a.creator_id WHERE a.status_cd = '00A' AND a.bot_status = '1'
AND a.tenant_id = #{params.tenantId}
AND a.tenant_id IN (SELECT tenant_id FROM bt_tenant WHERE status_cd = '00A' AND space_id = #{params.spaceId})
AND a.bot_name LIKE
#{params.searchContent}
AND NOT EXISTS(SELECT 1 FROM bt_workbench_app_rel b WHERE b.status_cd = '00A' AND b.rel_app_id = a.bot_id AND b.rel_app_type = 'aiBot' AND b.space_id = #{params.spaceId}
AND b.rel_app_id NOT IN (#{selectedAppId} )
)
ORDER BY a.created_time DESC, a.bot_id DESC

SELECT a.bot_id AS "botId", a.tenant_id AS "tenantId", a.bot_name AS "appName", a.bot_use AS "appDesc" FROM bt_bot a WHERE a.status_cd = '00A' AND a.tenant_id = #{tenantId} AND a.bot_status = '1'
AND (a.bot_name LIKE
#{params.keyword}
OR a.bot_use LIKE
#{params.keyword}
)
ORDER BY a.updated_time DESC

SELECT a.bot_id, a.bot_name, a.tenant_id, a.bot_use, 'T' AS "isBoteClaw"
FROM bt_bot a
WHERE a.status_cd = '00A'
  AND a.data_from = '10A'
  AND a.tenant_id = #{params.spaceId}
  AND a.creator_id = #{params.userId}

  AND a.bot_name LIKE

  #{params.searchContent}

SELECT bot_id, bot_name, tenant_id, bot_use
FROM bt_bot
WHERE status_cd = '00A'
  AND data_from = '10A'
  AND tenant_id = #{spaceId}
  AND creator_id = #{userId}

SELECT * FROM ( SELECT a.bot_id, a.bot_name, a.bot_use, a.tenant_id, 'T' AS isCreator FROM bt_bot a WHERE a.status_cd = '00A' AND a.data_from = '10A' AND a.tenant_id = #{query.tenantId} AND a.creator_id = #{query.userId}
AND a.bot_name LIKE
#{query.searchContent}
UNION ALL SELECT a.bot_id, MAX(b.bot_name) as bot_name, MAX(b.bot_use) as bot_use, MAX(a.owner_tenant_id) as tenant_id, 'F' AS isCreator FROM bt_bot_auth a JOIN bt_bot b on a.bot_id = b.bot_id and b.tenant_id = a.owner_tenant_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND b.bot_status = '1' AND a.auth_status = 'T' AND a.data_from = '10A'
AND a.auth_tenant_id IN (#{query.tenantId}, -1) AND a.user_id IN (#{query.userId}, -1) AND a.org_id IN ( #{orgId} )
AND b.bot_name LIKE
#{query.searchContent}
GROUP BY a.bot_id ) temp_result
